// purely percentage-based sizing chain (root -> scrollContainer -> slide, deliberately fluid
// to fill an arbitrary real CSS Grid cell in production) with no definite width to resolve
// against — confirmed live in Chrome: the decorator itself collapsed to 8px wide and the
// whole media root/img followed it down to ~8x12px in every single-image story.
(Story) => (
  <Box width="320px">
    <Story />
  </Box>
),

