// Ad-hoc real-browser verification script — NOT part of the repo, scratchpad only.
// Launches real Chromium (via the project's already-installed Playwright), navigates to each
// ZimmProductCardMedia story's Storybook iframe directly, and measures the live
// getBoundingClientRect() of [data-card-slot="media"] plus the decorator Box itself.
const { chromium } = require('playwright');

const STORY_IDS = [
  'commerce-zimmproductcardmedia--default',
  'commerce-zimmproductcardmedia--with-hover-swap',
  'commerce-zimmproductcardmedia--multiple-images',
  'commerce-zimmproductcardmedia--with-badge',
  'commerce-zimmproductcardmedia--with-remove-button',
  'commerce-zimmproductcardmedia--single-image',
];

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const results = [];

  for (const id of STORY_IDS) {
    const url = `http://localhost:6006/iframe.html?id=${id}&viewMode=story`;
    await page.goto(url, { waitUntil: 'networkidle' });
    // Give any hover-image / lazy content a moment to settle.
    await page.waitForTimeout(300);

    const measurement = await page.evaluate(() => {
      const media = document.querySelector('[data-card-slot="media"]');
      const img = document.querySelector('[data-card-slot="media"] img');
      // The decorator's own Box is the direct wrapper Storybook mounts the story into;
      // walk up from the media root to find it (first ancestor whose own width we set).
      let decorator = media ? media.parentElement : null;
      while (decorator && decorator !== document.body) {
        const cs = window.getComputedStyle(decorator);
        if (cs.width === '320px') break;
        decorator = decorator.parentElement;
      }
      const rect = (el) => (el ? el.getBoundingClientRect() : null);
      const mediaRect = rect(media);
      const imgRect = rect(img);
      const decoratorRect = rect(decorator);
      return {
        found: !!media,
        decorator: decoratorRect ? { width: decoratorRect.width, height: decoratorRect.height } : null,
        media: mediaRect ? { width: mediaRect.width, height: mediaRect.height } : null,
        img: imgRect ? { width: imgRect.width, height: imgRect.height } : null,
      };
    });

    results.push({ id, ...measurement });
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})().catch((err) => {
  console.error('VERIFY_SCRIPT_ERROR', err);
  process.exit(1);
});

